const upsertERPTokens = `-- name: UpsertERPTokens :exec

WITH evict AS (
    DELETE FROM toro_core.erp_connections
    WHERE entity_id = $1 AND realm_id != $2 AND erp_system = $3
)
INSERT INTO toro_core.erp_connections (entity_id, realm_id, erp_system, access_token, refresh_token, expires_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (erp_system, realm_id)
DO UPDATE SET
    entity_id     = EXCLUDED.entity_id,
    access_token  = EXCLUDED.access_token,
    refresh_token = EXCLUDED.refresh_token,
    expires_at    = EXCLUDED.expires_at,
    updated_at    = NOW()
`

type UpsertERPTokensParams struct {
	EntityID     pgtype.UUID
	RealmID      string
	ErpSystem    string
	AccessToken  string
	RefreshToken string
	ExpiresAt    pgtype.Timestamptz
}

// =========================================================================
// QBO Connection / Token Management
// =========================================================================
// Evict any connection the incoming entity already owns under a different realm
// before upserting, so the UNIQUE(entity_id) constraint never blocks a transfer.
func (q *Queries) UpsertERPTokens(ctx context.Context, arg UpsertERPTokensParams) error {
	_, err := q.db.Exec(ctx, upsertERPTokens,
		arg.EntityID,
		arg.RealmID,
		arg.ErpSystem,
		arg.AccessToken,
		arg.RefreshToken,
		arg.ExpiresAt,
	)
	return err
}

